import { Component, OnInit } from '@angular/core';
import { DestinationService } from '../../../services/destination.service';
import { Destination } from '../../../models/destination.model';

@Component({
    selector: 'app-suggestions',
    templateUrl: './suggestions.component.html',
    styleUrls: ['./suggestions.component.css']
})
export class SuggestionsComponent implements OnInit {
    suggestions: any[] = [];
    loading = false;
    error = '';
    successMessage = '';

    selectedDestinations: Set<any> = new Set();

    constructor(private destinationService: DestinationService) { }

    ngOnInit(): void {
        this.loadSuggestions();
    }

    loadSuggestions() {
        this.loading = true;
        this.destinationService.getSuggestions()
            .subscribe({
                next: (response) => {
                    this.suggestions = response.data; // backend returns list of Destination
                    this.loading = false;
                },
                error: (e) => {
                    this.error = 'Failed to load suggestions from backend API';
                    this.loading = false;
                    console.error(e);
                }
            });
    }

    // Toggle Selection for Bulk Action
    toggleSelection(dest: any) {
        if (this.selectedDestinations.has(dest)) {
            this.selectedDestinations.delete(dest);
        } else {
            this.selectedDestinations.add(dest);
        }
    }

    isSelected(dest: any): boolean {
        return this.selectedDestinations.has(dest);
    }

    // New Bulk Add Method
    addSelectedToDatabase() {
        if (this.selectedDestinations.size === 0) return;

        if (!confirm(`Are you sure you want to add ${this.selectedDestinations.size} destinations to the public database?`)) return;

        // Map selected items to clean DTOs
        const requests = Array.from(this.selectedDestinations).map(dest => ({
            country: dest.country,
            capital: dest.capital,
            region: dest.region,
            population: dest.population,
            currency: dest.currency,
            flagImageUrl: dest.flagImageUrl,
            description: dest.description || `Explore the beauty of ${dest.country}`
        }));

        this.loading = true;
        this.destinationService.bulkAddDestinations(requests).subscribe({
            next: (response) => {
                this.successMessage = `Successfully added ${requests.length} destinations!`;

                // Remove added items from the list
                this.suggestions = this.suggestions.filter(s => !this.selectedDestinations.has(s));
                this.selectedDestinations.clear();

                this.loading = false;
                setTimeout(() => this.successMessage = '', 3000);
            },
            error: (e) => {
                console.error('Bulk add error:', e);
                alert('Failed to add destinations. detailed error in console.');
                this.loading = false;
            }
        });
    }

    addToDatabase(dest: any) {
        if (!confirm(`Add ${dest.country} to public destinations for users?`)) return;

        const request: any = {
            country: dest.country,
            capital: dest.capital,
            region: dest.region,
            population: dest.population,
            currency: dest.currency,
            flagImageUrl: dest.flagImageUrl,
            description: dest.description || `Explore the beauty of ${dest.country}`
        };

        this.destinationService.addDestination(request)
            .subscribe({
                next: () => {
                    this.successMessage = `${dest.country} is now visible to users!`;
                    this.suggestions = this.suggestions.filter(s => s.country !== dest.country);
                    setTimeout(() => this.successMessage = '', 3000);
                },
                error: (err) => {
                    alert('Failed to publish destination. Please try again.');
                    console.error(err);
                }
            });
    }
}
